import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1186, own='cte_109.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 773 Legal Research and Writing ----
H("773.d.1.A",3,"A law clerk is asked to find out whether a tenant can be evicted without notice. Before opening any database, she lists the legal issue, the key terms to search and the jurisdiction. She is:","planning a legal research strategy",["drafting a closing argument","filing a complaint","selecting a jury"],"Good research starts with a plan.")
H("773.d.1.A",4,"Which step belongs near the beginning of a legal research plan?","identifying the legal issue and the controlling jurisdiction",["printing the final brief","citing every case ever decided","scheduling the oral argument"],"Issue and jurisdiction guide the search.")
H("773.d.1.B",3,"A paralegal checks a bound reporter in the law library and then runs the same search in an online database to compare results. She is accessing:","print and online sources to find and analyze case law",["only social media posts","only newspaper ads","only personal diaries"],"Case law appears in print and online.")
H("773.d.1.B",4,"A published court opinion is usually found in a:","case reporter or legal database",["cookbook","atlas","thesaurus"],"Reporters collect opinions.")
H("773.d.1.C",3,"A Texas trial court must follow a ruling of the Texas Supreme Court, but may only consider a similar ruling from a court in Oregon. The Oregon ruling is:","persuasive authority",["mandatory authority","binding precedent","a statute"],"Other-jurisdiction cases persuade but do not bind.")
H("773.d.1.C",4,"Authority that a court must follow because it comes from a higher court in the same jurisdiction is called:","mandatory authority",["persuasive authority","secondary dictum","an advisory memo"],"Binding vs. persuasive.")
H("773.d.1.D",3,"An intern searches a subscription legal database by keyword and filters results by court and date to locate controlling cases. She is researching:","mandatory and persuasive case history using online databases",["recipes with a search engine","sports scores with an app","flight prices with a website"],"Databases such as Lexis or Westlaw filter case law.")
H("773.d.1.D",4,"Filtering search results by jurisdiction helps a researcher mainly to:","find cases that actually bind the court",["shorten the font size","hide older cases only","avoid reading opinions"],"Jurisdiction filtering targets binding law.")
H("773.d.1.E",3,"Before relying on an old case in a brief, an attorney runs a citator check to see whether later courts overruled or criticized it. She is:","shepardizing the case",["translating the case","printing the case","indexing the case"],"Citators confirm a case is still good law.")
H("773.d.1.E",4,"The main reason to shepardize a case is to confirm that it is:","still good law",["short enough","recent enough to be new","written clearly"],"Subsequent history matters.")
H("773.d.1.F",3,"A student reading a classmate's memo notices that one quoted case was later reversed and another citation has no page number. She is critiquing:","legal writing for accurate cited authority",["a poem for rhyme","a recipe for spice","a map for scale"],"Check that authority is accurate and complete.")
H("773.d.1.F",4,"When critiquing a legal memo, a reviewer should confirm that each cited case actually:","supports the point it is cited for",["has a catchy name","is under ten pages","was decided this year"],"Citations must support the proposition.")
H("773.d.1.G",3,"A student formats a case citation with the party names, volume, reporter, page and year in the order a style manual requires. She is applying:","Bluebook citation rules",["MLA bibliography rules","recipe card rules","sports scoring rules"],"The Bluebook sets legal citation format.")
H("773.d.1.G",4,"Which tool is the standard guide for how lawyers format citations in briefs?","the Bluebook",["a thesaurus","an almanac","a field guide"],"Bluebook = legal citation format.")
H("773.d.2.A",3,"A student reads a court opinion and writes down who sued whom, the facts, the question the court answered and the ruling. She is:","reading and analyzing case law",["memorizing a statute number","drafting a contract","filing a motion"],"Brief the facts, issue and holding.")
H("773.d.2.A",4,"The part of an opinion that states the court's answer to the legal question is the:","holding",["caption","docket","exhibit list"],"The holding is the rule applied.")
H("773.d.2.B",3,"A researcher traces a case from the trial court through the appeals court and into a higher court review. She is analyzing the case's:","procedural history",["spelling history","price history","family history"],"Procedural history shows how the case moved.")
H("773.d.2.B",4,"A court that reviews a lower court's decision for legal error is acting as an:","appellate court",["grand jury","small claims court only","municipal clerk"],"Appellate courts review decisions.")
H("773.d.2.C",3,"A lawyer finds an earlier case with nearly identical facts and argues the new case should be decided the same way. She is applying:","legal precedent",["a weather forecast","a sales pitch","a coin toss"],"Precedent guides like cases.")
H("773.d.2.C",4,"The principle that courts follow earlier decisions on the same legal issue is called:","stare decisis",["habeas corpus","voir dire","nolo contendere"],"Stare decisis means to stand by decided matters.")
H("773.d.2.D",3,"A student builds an argument using a statute, two cases and a policy reason why the rule serves the public. She is developing arguments based on:","research, relevant case law, statutes and public policy",["rumors and guesses","personal taste only","a random poll"],"Good legal argument cites authority and policy.")
H("773.d.2.D",4,"Which source is the strongest support for a legal argument?","a controlling statute or binding case",["a friend's opinion","a social media comment","a movie plot"],"Primary mandatory authority carries the most weight.")
H("773.d.3.A",3,"A new associate keeps a style manual open while editing a brief so every citation and quotation follows the same rules. She is using:","a legal reference document such as the Bluebook",["a travel brochure","a restaurant menu","a sports schedule"],"Reference manuals ensure consistency.")
H("773.d.3.A",4,"Following the Bluebook consistently helps a brief look:","professional and easy for a court to verify",["longer than needed","funnier","less organized"],"Standard citations let readers find sources.")
H("773.d.3.B",3,"A student drafts a brief with an introduction, statement of facts, argument and conclusion. She is preparing a:","legal brief with its standard elements",["grocery list","text thread","travel diary"],"Briefs follow a standard structure.")
H("773.d.3.B",4,"In a legal brief, the section that explains why the law favors the client is the:","argument",["caption","signature line","table of exhibits"],"The argument applies law to facts.")
H("773.d.3.C",3,"A junior attorney writes an internal document with a question presented, a brief answer, facts, discussion and conclusion to advise a partner. She is drafting a:","legal memorandum",["press release","menu","party invitation"],"Memos follow a set format.")
H("773.d.3.C",4,"A legal memorandum is mainly written to:","objectively analyze an issue for a colleague or client",["persuade a jury with emotion","entertain readers","advertise a firm"],"Memos are objective; briefs persuade.")
H("773.d.3.D",3,"A landlord's attorney writes a firm letter stating the amount owed and the deadline to pay before a lawsuit is filed. This document is a:","demand letter",["subpoena","verdict","warrant"],"Demand letters request action before suit.")
H("773.d.3.D",4,"A formal written statement of a party's claims or defenses filed with a court is called a:","pleading",["transcript","menu","receipt"],"Complaints and answers are pleadings.")
H("773.d.4.A",3,"A student maps how the U.S. Constitution outranks a state law, while common law fills in where no statute speaks. She is analyzing the:","relationship among constitutional, common, state and federal law",["relationship among school clubs","relationship among sports teams","relationship among fashion brands"],"Sources of law have a hierarchy.")
H("773.d.4.A",4,"When a state statute conflicts with the U.S. Constitution, the:","Constitution prevails",["state statute prevails","local custom prevails","older case prevails"],"The Constitution is the supreme law.")
H("773.d.4.B",3,"A class studies how a landmark ruling on school segregation changed communities and later laws. They are analyzing the legal, social and historical implications of:","court decisions affecting society",["weather patterns","sports trades","stock splits"],"Decisions have broad effects.")
H("773.d.4.B",4,"A landmark decision is important mainly because it:","sets a rule with lasting effects on later cases and society",["is the longest opinion","was reported first","has the most footnotes"],"Landmark = lasting impact.")
H("773.d.4.C",3,"After reading several rulings on police searches of phones, a student predicts how a court might rule on a new but similar case. She is:","predicting outcomes and framing arguments in light of precedent",["flipping a coin","reading tea leaves","guessing at random"],"Prediction uses precedent trends.")
H("773.d.4.C",4,"A reliable prediction of how a court will rule is based on:","precedent and the court's reasoning in similar cases",["the day of the week","the lawyer's clothing","the courtroom temperature"],"Precedent drives prediction.")
H("773.d.4.D",3,"A debate team reads a case on free speech in schools and writes a critique of the majority's reasoning and the dissent's response. They are critiquing a case on:","U.S. constitutional law",["gardening methods","cake decorating","swim technique"],"Constitutional cases can be evaluated critically.")
H("773.d.4.D",4,"A dissent in a court opinion is written by a judge who:","disagrees with the majority's decision",["wrote the majority opinion","did not read the case","was not on the court"],"Dissenters disagree.")
H("773.d.4.E",3,"A paralegal student evaluates a recent ruling on online privacy, noting strengths and weaknesses in the court's reasoning. She is critiquing a case on:","a current legal issue",["a historical recipe","an old map","a music chart"],"Evaluate cases on today's issues.")
H("773.d.4.E",4,"A strong critique of a court ruling explains:","what the court decided and whether its reasoning is sound",["only whether it was famous","only the length of the opinion","only who attended"],"Critique weighs reasoning.")
H("773.d.5.A",3,"For a moot court problem on student searches, a team gathers recent cases from several courts and compares how each decided the issue. They are researching and evaluating:","case law on a current legal issue",["menu options","travel routes","movie reviews"],"Collect and compare cases.")
H("773.d.5.A",4,"When two courts reach different results on the same issue, researchers say the courts are:","split in their decisions",["in agreement","out of session","retired"],"A split signals unsettled law.")
H("773.d.5.B",3,"A moot court team reads the brief of the party who lost below, the brief of the party who won and a brief from a group not in the case that supports one side. They are reading:","appellant, respondent and amici briefs",["menus and receipts","posters and flyers","comics and cartoons"],"Amici file friend-of-the-court briefs.")
H("773.d.5.B",4,"An amicus curiae brief is filed by someone who:","is not a party but has an interest in the outcome",["is the judge","is the defendant","is the court reporter"],"Friend of the court.")
H("773.d.5.C",3,"A team writes a document asking a higher court to reverse the trial court, with a statement of the issues, facts and argument. They are writing an:","appellate brief",["birthday card","grocery list","game schedule"],"Appellate briefs argue error below.")
H("773.d.5.C",4,"An appellant's brief argues that the lower court:","made a legal error that should be corrected",["was too slow","used a nice courtroom","had a short docket"],"Appeals claim error.")
H("773.d.5.D",3,"A student stands before three judges, presents her side in a few minutes and answers their pointed questions about the law. She is giving an:","oral argument",["opening toast","pep talk","sales demo"],"Oral argument includes questions from the bench.")
H("773.d.5.D",4,"When a judge interrupts with a question during oral argument, the best response is to:","answer directly and tie the answer back to the law",["ignore the question","argue with the judge","read the brief aloud"],"Respond to the bench directly.")

# ---- 800 Practicum in Law and Public Safety ----
H("800.d.1.A",3,"At a county records office practicum, an intern notices the written procedure for signing out files but is in a hurry and skips it. The best choice is to:","follow the posted policy and sign out the file",["skip the policy to save time","ask a friend to sign for her","take the file without telling anyone"],"Policies protect records and people.")
H("800.d.1.A",4,"Why do public safety workplaces require staff to follow written procedures?","they keep work consistent, safe and legally defensible",["they make jobs longer on purpose","they are only suggestions","they matter only to supervisors"],"Procedures protect everyone.")
H("800.d.1.B",3,"A practicum student arrives ten minutes early each day, plans her tasks and finishes assignments before deadlines. These are examples of positive:","work behaviors such as punctuality and time management",["social media habits","hobby choices","clothing styles"],"Reliability shows professionalism.")
H("800.d.1.B",4,"Which behavior best shows a positive attitude at a placement site?","volunteering for needed tasks and staying courteous",["complaining about assignments","arriving late but staying late","doing only what is asked"],"Initiative and courtesy.")
H("800.d.1.C",3,"A supervisor tells an intern that her incident report was missing key details. The intern should:","listen, thank the supervisor and revise the report",["argue that the report was perfect","avoid the supervisor afterward","blame a coworker"],"Constructive criticism improves work.")
H("800.d.1.C",4,"Constructive criticism is most useful when it is:","specific and aimed at improving future work",["vague and personal","public and humiliating","given only once a year"],"Specific feedback improves performance.")
H("800.d.1.D",3,"A security intern finds a lost wallet with cash inside and no one around. Applying ethical reasoning, she should:","turn it in to the proper authority with the contents intact",["keep the cash and turn in the wallet","leave it where it is","spend the cash on lunch"],"Ethical decisions follow honesty and duty.")
H("800.d.1.D",4,"Ethical reasoning in a public safety job means:","weighing choices by honesty, fairness and the rules",["doing whatever is easiest","following the loudest voice","protecting only friends"],"Think through right and wrong.")
H("800.d.1.E",3,"A trainee double-checks a dispatch log twice before submitting it so no address is wrong. This shows:","completing tasks to the highest standard to ensure quality service",["rushing to finish early","ignoring details","avoiding responsibility"],"Accuracy matters in public safety.")
H("800.d.1.E",4,"In emergency dispatch, a small error in an address can:","delay help from reaching the right place",["improve response time","have no effect at all","reduce paperwork"],"Quality prevents harm.")
H("800.d.1.F",3,"A job shadow in a jail teaches an intern the standards for confidentiality, use of force and respect for inmates' rights. These are professional standards in:","law, public safety, corrections and security",["retail, fashion and sales","farming and ranching","film and music"],"Fields have professional codes.")
H("800.d.1.F",4,"A professional standard that applies to most public safety jobs is:","keeping sensitive information confidential",["sharing reports online","posting case photos","gossiping about cases"],"Confidentiality is a core standard.")
H("800.d.1.G",3,"At a fire station practicum, an intern is told to wear gloves when handling equipment and to keep walkways clear. He is learning to:","comply with practicum safety rules and regulations",["avoid all equipment","ignore posted signs","disable alarms"],"Safety rules prevent injury.")
H("800.d.1.G",4,"If an intern sees a spill in a hallway at the practicum site, the best action is to:","report it or clean it up according to site procedure",["step over it","pretend not to notice","wait for someone to slip"],"Hazards must be handled promptly.")
H("800.d.2.A",3,"A security intern notices that visitors keep forgetting to sign in at the front desk. She breaks down the causes and proposes a bright sign-in kiosk. She is:","analyzing problem elements to develop creative solutions",["ignoring the problem","complaining to visitors","removing the desk"],"Break a problem into parts, then solve.")
H("800.d.2.A",4,"The first step in creative problem solving is usually to:","define the problem and its causes clearly",["pick the cheapest option","blame someone","skip to implementation"],"Define before solving.")
H("800.d.2.B",3,"An intern receives three conflicting reports about a parking incident and checks the source, date and detail of each before deciding what to rely on. She is:","critically analyzing information for its value",["ignoring all reports","believing the loudest report","accepting the first report"],"Evaluate reliability.")
H("800.d.2.B",4,"Which question best tests whether a source of information is reliable?","who produced it and how do they know?",["does it use big fonts?","is it long?","is it popular online?"],"Check source credibility.")
H("800.d.2.C",3,"A trainee lists two ways to route patrol cars and compares speed, cost and coverage before recommending one. He is:","comparing and contrasting alternatives using critical thinking",["flipping a coin","copying a classmate","guessing"],"Weigh pros and cons.")
H("800.d.2.C",4,"A decision matrix helps a team choose by:","scoring each option against the same criteria",["asking only the boss","choosing the first idea","avoiding data"],"Consistent criteria.")
H("800.d.2.D",3,"Before recommending a new radio system, an intern reads manufacturer specifications and agency reports to gather facts. She is conducting:","technical research to support decision making",["random browsing","a casual chat","party planning"],"Decisions need technical facts.")
H("800.d.2.D",4,"Reliable technical research for a purchase decision should rely on:","specifications, test data and expert reports",["rumors","advertising slogans","hunches"],"Use evidence.")
H("800.d.3.A",3,"A sergeant earns her team's confidence by keeping promises, admitting mistakes and staying positive in tough shifts. She is showing leadership characteristics such as:","trust, positive attitude and integrity",["secrecy and pride","impatience and blame","favoritism and gossip"],"Leaders build trust.")
H("800.d.3.A",4,"Which action most builds trust in a leader?","doing what she said she would do",["avoiding feedback","taking credit for others' work","changing rules randomly"],"Consistency builds trust.")
H("800.d.3.B",3,"Three interns share a training scenario, each handling a different part so that the group finishes on time. They are demonstrating:","teamwork by cooperating to achieve a goal",["working alone","competing against each other","avoiding the task"],"Teams share the load.")
H("800.d.3.B",4,"Effective teamwork depends most on team members:","sharing information and supporting each other",["hiding mistakes","working in isolation","avoiding communication"],"Cooperation wins.")
H("800.d.3.C",3,"A shift group struggles to agree on a duty schedule. They list options, listen to each person and settle on a compromise everyone accepts. This demonstrates:","team processes such as consensus building and conflict resolution",["avoiding the problem","letting one person decide","walking away"],"Consensus resolves conflict.")
H("800.d.3.C",4,"Consensus building means:","working until everyone can accept the decision",["the loudest person wins","the majority forces others","the leader ignores input"],"Everyone can live with it.")
H("800.d.3.D",3,"Two interns agree to split a report. One writes her half on time while the other asks to be excused. The responsible intern shows:","responsibility for shared group and individual work tasks",["indifference","avoidance","blame"],"Meet your commitments.")
H("800.d.3.D",4,"Taking responsibility for a group task includes:","finishing your part and telling the team if you need help",["waiting for someone else","hiding that you're late","blaming the schedule"],"Own your piece.")
H("800.d.3.E",3,"A police cadet takes time to learn her partner's work style, shares credit for good outcomes and settles small disagreements calmly. She is:","maintaining effective working relationships",["creating cliques","avoiding teammates","competing for attention"],"Good relationships support missions.")
H("800.d.3.E",4,"A good working relationship at a public safety agency usually relies on:","mutual respect and clear communication",["secrecy","rivalry","favoritism"],"Respect and clarity.")
H("800.d.3.F",3,"A security intern greets visitors politely, listens to complaints and thanks coworkers for help. She is demonstrating effective working relationships using:","interpersonal skills",["technical manuals","office furniture","stationery"],"Interpersonal skills build relationships.")
H("800.d.3.F",4,"Which is an interpersonal skill?","listening to understand before responding",["typing quickly","memorizing codes","lifting heavy objects"],"Listening is interpersonal.")
H("800.d.3.G",3,"A corrections intern is paired with a coworker whose style differs from hers. She asks questions, adjusts her pace and offers help. She is applying:","positive interpersonal skills to work cooperatively",["avoidance","blame","hostility"],"Cooperation despite differences.")
H("800.d.3.G",4,"When a coworker does a task differently than you would, the best first step is to:","ask about their approach and look for common ground",["mock their method","refuse to help","report them at once"],"Seek understanding.")
H("800.d.3.H",3,"A deputy treats an elderly witness, a teen and a visitor from another country with the same courtesy. He is demonstrating:","respect for individuals from different cultures, genders and backgrounds",["ranking people by age","assuming roles by looks","ignoring differences"],"Respect applies to everyone.")
H("800.d.3.H",4,"Showing respect for cultural differences at work includes:","avoiding assumptions and learning about others' customs",["making jokes about customs","ignoring customs","insisting everyone act alike"],"Learn, don't assume.")
H("800.d.3.I",3,"A hiring panel for a security firm values employees who bring different languages, backgrounds and ideas to solve problems. This shows sensitivity to and value for:","diversity",["uniformity","isolation","secrecy"],"Diversity strengthens teams.")
H("800.d.3.I",4,"A workplace benefits from diversity mainly because:","different viewpoints help solve problems and serve more people",["everyone thinks the same","it avoids all conflict","it lowers wages"],"Variety improves solutions.")
H("800.d.4.A",3,"In a briefing, a trainee uses terms such as 'chain of custody' and 'probable cause' correctly when explaining a scenario. She is demonstrating:","use of content, technical concepts and vocabulary when analyzing information",["slang for fun","avoidance of detail","random word choice"],"Precise vocabulary shows understanding.")
H("800.d.4.A",4,"Using correct technical terms in a report helps the reader:","understand exactly what was done",["skim faster","skip steps","guess the meaning"],"Precision prevents confusion.")
H("800.d.4.B",3,"A dispatcher intern asks open questions to get the caller's location, then repeats the address back to confirm. She is employing:","verbal skills when obtaining and conveying information",["written notes only","silence","gestures only"],"Clear speech and confirmation.")
H("800.d.4.B",4,"Repeating back an address to a caller is done to:","confirm the information is correct",["slow the call","impress the caller","avoid writing it"],"Read-back confirms.")
H("800.d.4.C",3,"An intern checks a state agency manual and a department database to find the correct form for a report. She is accessing:","information sources for occupational tasks using technical materials",["entertainment websites","social posts","unrelated menus"],"Use job references.")
H("800.d.4.C",4,"When you cannot remember a procedure at work, the best approach is to:","consult the official manual or ask a supervisor",["guess","make one up","skip it"],"Official sources first.")
H("800.d.4.D",3,"An intern compares a trade magazine's claim with the agency's published policy and notes the policy is more recent and official. She is:","evaluating the reliability of information from technical materials",["accepting everything","avoiding reading","copying text"],"Check recency and authority.")
H("800.d.4.D",4,"An official policy is generally more reliable than an unsigned online post because it:","comes from an accountable, authoritative source",["has more images","has more likes","is longer"],"Accountability matters.")
H("800.d.4.E",3,"A security trainee sees a visitor clenching fists and avoiding eye contact while saying 'I'm fine.' She takes extra care to ask follow-up questions. She is interpreting:","verbal and nonverbal behaviors to enhance communication",["only spoken words","only written text","only the weather"],"Nonverbal cues add meaning.")
H("800.d.4.E",4,"Which nonverbal cue most likely signals discomfort?","crossed arms and avoiding eye contact",["steady relaxed posture","a calm tone","a nod"],"Body language communicates.")
H("800.d.4.F",3,"While taking a witness statement, a trainee puts down her phone, nods and asks, 'So the car turned left, correct?' She is applying:","active listening skills to obtain and clarify information",["interrupting often","multitasking","finishing the sentence for the witness"],"Active listening clarifies.")
H("800.d.4.F",4,"Paraphrasing what a speaker said is a form of:","active listening",["interrupting","arguing","note forgery"],"Paraphrase to confirm.")
H("800.d.4.G",3,"A trainee uses grammar, spelling and clear organization to write a concise incident report that a supervisor can read quickly. She is using:","academic skills to facilitate effective written communication",["slang","abbreviations only","emoji"],"Clear writing is professional.")
H("800.d.4.G",4,"A strong incident report is:","clear, accurate and organized in a logical order",["vague and emotional","long and rambling","full of opinions"],"Reports should be factual.")
H("800.d.5.A",3,"An intern asks a supervising officer to let him practice basic report writing and radio use under supervision to build skills for his chosen career. He is developing:","advanced technical knowledge and skills related to the occupation",["only hobby skills","generic chat skills","unrelated skills"],"Practicums build job skills.")
H("800.d.5.A",4,"A supervised practicum helps a student by:","giving real-world practice with guidance",["replacing all classes","avoiding real tasks","eliminating the need for skills"],"Real practice with support.")
H("800.d.5.B",3,"After a mock traffic stop, an intern lists what went well and what slipped, such as forgetting to confirm identification. She is:","evaluating strengths and weaknesses in technical skill proficiency",["hiding errors","ignoring feedback","boasting"],"Self-assessment finds growth areas.")
H("800.d.5.B",4,"Identifying weaknesses honestly lets a trainee:","target practice where it's needed most",["avoid training","hide mistakes","repeat strengths only"],"Target growth.")
H("800.d.5.C",3,"A supervisor points out that the intern's evidence labels were hard to read. The intern says, 'Thank you, I'll print them clearly next time.' This shows she can:","accept critical feedback from a supervisor",["argue back","ignore feedback","blame others"],"Respond to feedback professionally.")
H("800.d.5.C",4,"The best response to critical feedback from a supervisor is to:","listen, ask clarifying questions and apply the advice",["defend every mistake","take offense","stop asking for help"],"Use it to improve.")
H("800.d.6.A",3,"At the end of a semester, an intern adds her certificates, a sample incident report and a supervisor's evaluation to a folder that shows her best work. She is updating a:","professional portfolio",["wallet","photo album","phone case"],"Portfolios show work quality.")
H("800.d.6.A",4,"Which item belongs in a professional portfolio?","a work sample and a letter of recommendation",["a joke list","a game score","a party invite"],"Portfolios show evidence of skill.")
H("800.d.6.B",3,"For a mock job interview, a student shares her portfolio with a panel of local officers and explains how each item shows a skill. She is:","presenting the portfolio to interested stakeholders",["hiding her work","only reading a list","avoiding questions"],"Share and explain.")
H("800.d.6.B",4,"When presenting a portfolio, it helps to:","explain what each item shows and what you learned",["read every page word for word","avoid eye contact","skip samples"],"Connect items to skills.")
# ---- 801 Extended Practicum in Law and Public Safety ----
H("801.d.1.A",3,"During a ride-along, a trainee describes a minor accident to a dispatcher in short, clear sentences with the street name, number of vehicles and any injuries. This is:","clear, concise and accurate verbal communication",["rambling description","guessing at details","silent observation"],"Be clear and concise.")
H("801.d.1.A",4,"In a radio report, the most useful details come first, such as:","the location and the nature of the emergency",["the weather last week","your lunch order","a joke"],"Priority information first.")
H("801.d.1.B",3,"After a mock patrol, a student organizes her notes into a short summary with times, observations and data so a supervisor can quickly follow it. She is:","analyzing and effectively communicating information and observations",["hiding her notes","only sketching","discarding data"],"Summaries make data usable.")
H("801.d.1.B",4,"Which report entry is most useful to a supervisor?","a factual note with time, place and what was observed",["a guess about motives","a personal opinion","a funny remark"],"Objective facts.")
H("801.d.1.C",3,"A trainee notices a resident's shaky voice and tight grip on a bag while saying everything is fine. She adjusts her approach to be calmer. She is observing and interpreting:","verbal and nonverbal cues",["only spelling","only numbers","only clothing brands"],"Cues reveal feelings.")
H("801.d.1.C",4,"A calm tone and open posture can help a trainee:","reduce tension when speaking with a worried person",["increase conflict","end the conversation","show dominance"],"Calm de-escalates.")
H("801.d.1.D",3,"A trainee at a reception desk summarizes a visitor's request back to the visitor before answering. She is:","applying active listening skills to obtain and clarify information",["interrupting","ignoring","assuming"],"Summarize to confirm.")
H("801.d.2.A",3,"During a fire drill, a trainee notices that a rear exit is blocked by a stack of boxes and independently proposes moving the boxes and adding a floor marking. She is employing:","critical-thinking skills independently and with a team",["avoidance","imitation","random action"],"Critical thinking solves problems.")
H("801.d.2.A",4,"A team facing a recurring jam at a security checkpoint should first:","examine the process to find where the delay occurs",["blame the visitors","shut the checkpoint","ignore the line"],"Find the cause.")
H("801.d.2.B",3,"A trainee breaks a long report-writing backlog into causes such as unclear forms and too few templates, then proposes a checklist. She is:","analyzing elements of a problem to develop creative and innovative solutions",["overlooking the issue","assigning blame","dropping the task"],"Analyze, then create.")
H("801.d.2.C",3,"Before choosing a vendor for evidence bags, the trainee reviews product specifications, price lists and reviews from other agencies. She is conducting:","technical research to gather information for decision making",["a social poll","a guess","a coin flip"],"Gather technical facts.")
H("801.d.3.A",3,"On the first day at a police records office, a trainee reads the safety binder and follows rules about lifting boxes, handling sharps and fire exits. He is:","demonstrating an understanding of and consistently following workplace safety rules",["ignoring rules","skipping orientation","bending rules"],"Know and follow safety rules.")
H("801.d.3.A",4,"The main purpose of workplace safety rules is to:","prevent injury and protect people and property",["slow down work","punish workers","fill binders"],"Safety first.")
H("801.d.3.B",3,"A trainee slips on a wet floor and bruises her elbow. She tells her supervisor right away and fills out the incident form. She is following:","procedures for reporting and handling accidents and safety hazards",["secrecy","gossip","delay"],"Report accidents promptly.")
H("801.d.3.B",4,"After an accident at work, the first thing a trainee should do is:","make sure people are safe and report it to a supervisor",["leave quietly","post about it online","wait a week"],"Safety and reporting.")
H("801.d.4.A",3,"A trainee arrives on time, completes each assigned task as instructed and asks what to do when finished. He is demonstrating:","a positive, productive work ethic",["laziness","avoidance","entitlement"],"Work ethic shows reliability.")
H("801.d.4.A",4,"A new corrections trainee is given a stack of filing duties on a slow afternoon. Which choice reflects a strong work ethic?","finishing every file accurately without being reminded",["waiting until a supervisor checks","filing only the easy ones","leaving the rest for the next shift"],"Reliable self-directed effort.")
H("801.d.4.B",3,"A trainee is offered a small gift by a vendor who wants a favor on a purchase. She considers the agency's rules and fairness and politely declines. She is:","applying ethical reasoning to make an ethical decision",["accepting quietly","ignoring the offer","asking for more"],"Gifts can bias decisions.")
H("801.d.4.B",4,"Accepting a gift in exchange for a favor is a problem because it can:","create a conflict of interest",["improve fairness","build trust in the agency","reduce work"],"Conflict of interest.")
H("801.d.4.C",3,"A security trainee is tempted to skip a required badge check for a friendly visitor. She remembers that all rules apply consistently and checks the badge anyway. She is:","complying with all applicable rules, laws and regulations in a consistent manner",["bending rules for friends","skipping checks","ignoring laws"],"Rules apply equally.")
H("801.d.5.A",3,"Under supervision, a student leads a short community safety talk, writes a log of what she did and reflects on how it went. She is:","conducting, documenting and evaluating learning activities in a supervised setting",["acting alone without a log","skipping documentation","avoiding feedback"],"Do, document, evaluate.")
H("801.d.5.B",3,"An intern requests extra training on the agency's reporting software so she can enter data faster and more accurately. She is:","developing advanced technical knowledge and skills related to the occupation",["avoiding tools","skipping training","outsourcing the work"],"Build job-specific skills.")
H("801.d.5.C",3,"A trainee keeps a glossary of job terms such as 'incident,' 'citation' and 'custody' and uses them correctly in conversations with staff. He is:","examining and articulating job-specific technical vocabulary",["avoiding words","using slang","guessing meanings"],"Know the vocabulary.")
H("801.d.5.D",3,"After a practice exercise in evidence packaging, the trainee rates her accuracy and speed and notes she needs to slow down on labeling. She is:","evaluating strengths and weaknesses in technical skill proficiency",["boasting","hiding results","ignoring the exercise"],"Self-evaluation guides practice.")
H("801.d.5.E",3,"At the end of an internship, a student saves a sample report, a training certificate and a supervisor's evaluation in a folder. She is:","collecting representative work samples",["tossing records","avoiding evidence","copying others' work"],"Work samples show ability.")
H("801.d.1.D",4,"Which habit best shows active listening during a call or visit?","asking follow-up questions to clarify what was said",["checking your phone","finishing the speaker's sentences","changing the subject"],"Clarifying questions show active listening.")
H("801.d.2.B",4,"After identifying causes of a problem, the next step toward a solution is to:","brainstorm possible solutions and compare them",["pick the first idea","cancel the project","ignore the findings"],"Generate options before choosing.")
H("801.d.2.C",4,"A key reason to research technical details before a purchase decision is to:","make sure the choice meets the agency's needs",["delay the purchase","impress coworkers","avoid decisions"],"Research supports good decisions.")
H("801.d.4.C",4,"If a rule seems inconvenient but still applies, a public safety worker should:","follow it and raise concerns through proper channels",["ignore it quietly","break it once","change it alone"],"Follow rules; use channels to change them.")
H("801.d.5.A",4,"A learning log kept during a supervised practicum is useful because it:","records activities and reflections that show growth",["replaces supervision","avoids evaluation","hides mistakes"],"Logs document learning.")
H("801.d.5.B",4,"Advanced technical skills for a career are best developed through:","guided practice with feedback",["occasional observation only","avoiding hands-on tasks","skipping training"],"Practice plus feedback.")
H("801.d.5.C",4,"Why learn job-specific vocabulary in a practicum?","it helps you communicate precisely with colleagues",["it replaces skills","it makes work longer","it is only for tests"],"Vocabulary supports clear communication.")
H("801.d.5.D",4,"Honest self-evaluation of skills helps a trainee:","focus practice on the areas that need improvement",["avoid feedback","look more skilled","skip practice"],"Self-evaluation directs practice.")
H("801.d.5.E",4,"Work samples collected during a practicum are useful later because they:","show employers actual examples of your skills",["replace the interview","hide weaknesses","avoid references"],"Samples prove ability.")
B.balance()
